static int cmp(const void *a, const void *b) {
  return *(int *)a - *(int *)b;
}

static int dfs(int **land, int rows, int cols, int r, int c) {
  if (r < 0 || r >= rows || c < 0 || c >= cols || land[r][c] != 0) return 0;
  land[r][c] = -1;
  int size = 1;
  for (int dr = -1; dr <= 1; dr++) {
    for (int dc = -1; dc <= 1; dc++) {
      if (dr != 0 || dc != 0) size += dfs(land, rows, cols, r + dr, c + dc);
    }
  }
  return size;
}

int *pondSizes(int **land, int landSize, int *landColSize, int *returnSize) {
  int rows = landSize, cols = landColSize[0];
  int *res = (int *)malloc(sizeof(int) * (rows * cols + 1));
  *returnSize = 0;
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (land[i][j] == 0) res[(*returnSize)++] = dfs(land, rows, cols, i, j);
    }
  }
  qsort(res, *returnSize, sizeof(int), cmp);
  return res;
}

class Solution {
  int dfs(vector<vector<int>> &land, int r, int c) {
    if (r < 0 || r >= (int)land.size() || c < 0 || c >= (int)land[0].size() || land[r][c] != 0) return 0;
    land[r][c] = -1;
    int size = 1;
    for (int dr = -1; dr <= 1; dr++) {
      for (int dc = -1; dc <= 1; dc++) {
        if (dr != 0 || dc != 0) size += dfs(land, r + dr, c + dc);
      }
    }
    return size;
  }

public:
  vector<int> pondSizes(vector<vector<int>> &land) {
    vector<int> res;
    for (int i = 0; i < (int)land.size(); i++) {
      for (int j = 0; j < (int)land[0].size(); j++) {
        if (land[i][j] == 0) res.push_back(dfs(land, i, j));
      }
    }
    sort(res.begin(), res.end());
    return res;
  }
};

func pondSizes(land [][]int) []int {
	rows, cols := len(land), len(land[0])
	var dfs func(r, c int) int
	dfs = func(r, c int) int {
		if r < 0 || r >= rows || c < 0 || c >= cols || land[r][c] != 0 {
			return 0
		}
		land[r][c] = -1
		size := 1
		for dr := -1; dr <= 1; dr++ {
