class Solution {
  private int dfs(int[][] land, int r, int c) {
    if (r < 0 || r >= land.length || c < 0 || c >= land[0].length || land[r][c] != 0) return 0;
    land[r][c] = -1;
    int size = 1;
    for (int dr = -1; dr <= 1; dr++) {
      for (int dc = -1; dc <= 1; dc++) {
        if (dr != 0 || dc != 0) size += dfs(land, r + dr, c + dc);
      }
    }
    return size;
  }

  public int[] pondSizes(int[][] land) {
    List<Integer> res = new ArrayList<>();
    for (int i = 0; i < land.length; i++) {
      for (int j = 0; j < land[0].length; j++) {
        if (land[i][j] == 0) res.add(dfs(land, i, j));
      }
    }
    Collections.sort(res);
    return res.stream().mapToInt(Integer::intValue).toArray();
  }
}

class Solution:
    def pondSizes(self, land: List[List[int]]) -> List[int]:
        rows, cols = len(land), len(land[0])

        def dfs(r: int, c: int) -> int:
            if r < 0 or r >= rows or c < 0 or c >= cols or land[r][c] != 0:
                return 0
            land[r][c] = -1
            size = 1
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr or dc:
                        size += dfs(r + dr, c + dc)
            return size

        res = []
        for i in range(rows):
            for j in range(cols):
                if land[i][j] == 0:
                    res.append(dfs(i, j))
        res.sort()
        return res

impl Solution {
  pub fn pond_sizes(mut land: Vec<Vec<i32>>) -> Vec<i32> {
    let rows = land.len();
    let cols = land[0].len();
    fn dfs(land: &mut Vec<Vec<i32>>, r: i32, c: i32, rows: i32, cols: i32) -> i32 {
      if r < 0 || r >= rows || c < 0 || c >= cols || land[r as usize][c as usize] != 0 {
        return 0;
      }
      land[r as usize][c as usize] = -1;
      let mut size = 1;
      for dr in -1..=1 {
        for dc in -1..=1 {
          if dr != 0 || dc != 0 {
            size += dfs(land, r + dr, c + dc, rows, cols);
          }
        }
      }
      size
    }
    let mut res = vec![];
    for i in 0..rows {
      for j in 0..cols {
        if land[i][j] == 0 {
          res.push(dfs(&mut land, i as i32, j as i32, rows as i32, cols as i32));
        }
      }
    }
    res.sort();
    res
  }
}

const pondSizes = (land: number[][]): number[] => {
  const rows = land.length;
  const cols = land[0].length;
  const dfs = (r: number, c: number): number => {
    if (r < 0 || r >= rows || c < 0 || c >= cols || land[r][c] !== 0) return 0;
    land[r][c] = -1;
    let size = 1;
    for (let dr = -1; dr <= 1; dr++) {
      for (let dc = -1; dc <= 1; dc++) {
        if (dr !== 0 || dc !== 0) size += dfs(r + dr, c + dc);
      }
    }
    return size;
  };
  const res: number[] = [];
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      if (land[i][j] === 0) res.push(dfs(i, j));
    }
  }
  res.sort((a, b) => a - b);
  return res;
};
